//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns `true` for transient faults that may be retried.
    pub fn is_transient(&self) -> bool {
        matches!(self, RetryError::Transient(_))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn transient_errors_are_transient() {
        assert!(RetryError::Transient("blip".to_string()).is_transient());
    }

    #[test]
    fn permanent_errors_are_not_transient() {
        assert!(!RetryError::Permanent("bad input".to_string()).is_transient());
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Upper bound for every retry delay, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Creates a retry policy with bounded exponential backoff.
    pub fn new(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> Self {
        Self {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    /// Delay in milliseconds to wait before the `retry_index`-th retry
    /// (0-based). Delays grow exponentially from `base_delay_ms` and
    /// saturate at `max_delay_ms` without ever overflowing.
    pub fn delay_ms(&self, retry_index: u32) -> u64 {
        delay_ms(self.base_delay_ms, self.max_delay_ms, retry_index)
    }
}

/// Bounded exponential backoff: `base_delay_ms * 2^retry_index`, capped at
/// `max_delay_ms`. Overflow-safe for any retry count: the delay is doubled
/// with saturating arithmetic and stops growing once it reaches the cap.
fn delay_ms(base_delay_ms: u64, max_delay_ms: u64, retry_index: u32) -> u64 {
    if base_delay_ms >= max_delay_ms {
        return max_delay_ms;
    }
    let mut delay = base_delay_ms;
    let mut remaining = retry_index;
    while remaining > 0 && delay < max_delay_ms {
        delay = delay.saturating_mul(2).min(max_delay_ms);
        remaining -= 1;
    }
    delay
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn delay_grows_exponentially() {
        let cfg = RetryConfig::new(10, 10, 1_000);
        assert_eq!(cfg.delay_ms(0), 10);
        assert_eq!(cfg.delay_ms(1), 20);
        assert_eq!(cfg.delay_ms(2), 40);
        assert_eq!(cfg.delay_ms(3), 80);
    }

    #[test]
    fn delay_saturates_at_max_delay() {
        let cfg = RetryConfig::new(10, 10, 100);
        assert_eq!(cfg.delay_ms(0), 10);
        assert_eq!(cfg.delay_ms(3), 80);
        assert_eq!(cfg.delay_ms(4), 100);
        assert_eq!(cfg.delay_ms(1_000), 100);
    }

    #[test]
    fn delay_respects_cap_below_base() {
        let cfg = RetryConfig::new(3, 500, 100);
        assert_eq!(cfg.delay_ms(0), 100);
        assert_eq!(cfg.delay_ms(5), 100);
    }

    #[test]
    fn delay_never_overflows() {
        let saturating = RetryConfig::new(10, u64::MAX, u64::MAX);
        assert_eq!(saturating.delay_ms(0), u64::MAX);
        assert_eq!(saturating.delay_ms(u32::MAX), u64::MAX);

        let growing = RetryConfig::new(100, 1, u64::MAX);
        assert_eq!(growing.delay_ms(63), 1_u64 << 63);
        assert_eq!(growing.delay_ms(64), u64::MAX);
        assert_eq!(growing.delay_ms(u32::MAX), u64::MAX);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    // Rebinding keeps the public parameter (and signature) untouched while
    // allowing the `FnMut` closure to be called more than once.
    let mut job = job;
    for attempt in 0..config.max_attempts {
        match job() {
            Ok(()) => return Ok(()),
            // Only transient errors are retried, and only while a further
            // attempt is still available within `max_attempts`.
            Err(err) if err.is_transient() && attempt + 1 < config.max_attempts => {
                sleeper.sleep_ms(config.delay_ms(attempt));
            }
            Err(err) => return Err(err),
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn permanent_error_returns_immediately() {
        let config = RetryConfig::new(5, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("nope".to_string()))
        });
        assert_eq!(result, Err(RetryError::Permanent("nope".to_string())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn retries_transient_until_success() {
        let config = RetryConfig::new(5, 100, 1_000);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            if calls < 3 {
                Err(RetryError::Transient("not yet".to_string()))
            } else {
                Ok(())
            }
        });
        assert_eq!(result, Ok(()));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![100, 200]);
    }

    #[test]
    fn max_attempts_bounds_transient_retries() {
        let config = RetryConfig::new(3, 10, 1_000);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("always".to_string()))
        });
        assert_eq!(result, Err(RetryError::Transient("always".to_string())));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }
}

//! Integration coverage for the public retry-policy contract.
//!
//! These tests drive only the public API surface (`run_job`, `RetryConfig`,
//! `RetryError`, `FakeSleeper`) exactly as an external consumer would.

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn permanent_error_returns_immediately() {
    let config = RetryConfig::new(5, 10, 1_000);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("bad input".to_string()))
    });
    assert_eq!(result, Err(RetryError::Permanent("bad input".to_string())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn transient_errors_retry_with_exponential_delays() {
    let config = RetryConfig::new(5, 100, 1_000);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls < 4 {
            Err(RetryError::Transient("not yet".to_string()))
        } else {
            Ok(())
        }
    });
    assert_eq!(result, Ok(()));
    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps, vec![100, 200, 400]);
}

#[test]
fn max_attempts_includes_the_first_call() {
    let config = RetryConfig::new(3, 10, 1_000);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("always".to_string()))
    });
    assert_eq!(result, Err(RetryError::Transient("always".to_string())));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![10, 20]);
}

#[test]
fn delays_saturate_at_max_delay() {
    // base_delay = 1, so 2^10 = 1024 already exceeds the 1000 ms cap: the
    // 11th retry delay must be capped instead of growing past the bound.
    let config = RetryConfig::new(12, 1, 1_000);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("always".to_string()))
    });
    assert_eq!(result, Err(RetryError::Transient("always".to_string())));
    assert_eq!(calls, 12);
    assert_eq!(
        sleeper.sleeps,
        vec![1, 2, 4, 8, 16, 32, 64, 128, 256, 512, 1_000]
    );
}

#[test]
fn delay_never_overflows_for_extreme_retry_indices() {
    // Retry indices far past the safe exponent (63 with base 1) must
    // saturate at `max_delay_ms` rather than overflowing u64.
    let config = RetryConfig::new(10, u64::MAX, u64::MAX);
    assert_eq!(config.delay_ms(u32::MAX), u64::MAX);

    let config = RetryConfig::new(100, 1, u64::MAX);
    assert_eq!(config.delay_ms(63), 1_u64 << 63);
    assert_eq!(config.delay_ms(64), u64::MAX);
    assert_eq!(config.delay_ms(u32::MAX), u64::MAX);
}

#[test]
fn run_job_saturates_past_safe_exponent_without_overflow() {
    // 70 attempts with base 1: the retry indices past the safe exponent
    // (63) must saturate at `u64::MAX` instead of overflowing while the
    // job runs through the public `run_job` contract.
    let config = RetryConfig::new(70, 1, u64::MAX);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("always".to_string()))
    });
    assert_eq!(result, Err(RetryError::Transient("always".to_string())));
    assert_eq!(calls, 70);
    assert_eq!(sleeper.sleeps.len(), 69);
    assert_eq!(sleeper.sleeps[63], 1_u64 << 63);
    assert_eq!(sleeper.sleeps[64], u64::MAX);
    assert_eq!(sleeper.sleeps[68], u64::MAX);
}
